-- Aula SCADA: biblioteca de capacitación compartida. Ejecutar una vez en Supabase SQL Editor.
create table if not exists public.aula_scada_members(user_id uuid primary key references auth.users(id) on delete cascade,role text not null default 'viewer' check(role in('viewer','editor','admin')),created_at timestamptz not null default now());
create table if not exists public.aula_scada_screens(id uuid primary key default gen_random_uuid(),title text not null,area text,description text,image_path text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.aula_scada_comments(id uuid primary key default gen_random_uuid(),screen_id uuid not null references public.aula_scada_screens(id) on delete cascade,title text not null,content text not null,x double precision not null default 0,y double precision not null default 0,w double precision not null default .1,h double precision not null default .1,crop_path text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint aula_scada_comment_bounds check(x>=0 and y>=0 and w>0 and h>0 and x+w<=1.001 and y+h<=1.001));
create index if not exists aula_scada_comments_screen_idx on public.aula_scada_comments(screen_id,created_at);
alter table public.aula_scada_members enable row level security;alter table public.aula_scada_screens enable row level security;alter table public.aula_scada_comments enable row level security;
drop policy if exists "Aula members read" on public.aula_scada_members;create policy "Aula members read" on public.aula_scada_members for select to authenticated using(true);
drop policy if exists "Aula screens read" on public.aula_scada_screens;create policy "Aula screens read" on public.aula_scada_screens for select to authenticated using(true);
drop policy if exists "Aula screens insert" on public.aula_scada_screens;create policy "Aula screens insert" on public.aula_scada_screens for insert to authenticated with check(exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin')));
drop policy if exists "Aula screens update" on public.aula_scada_screens;create policy "Aula screens update" on public.aula_scada_screens for update to authenticated using(exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin'))) with check(exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin')));
drop policy if exists "Aula screens delete" on public.aula_scada_screens;create policy "Aula screens delete" on public.aula_scada_screens for delete to authenticated using(exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role='admin'));
drop policy if exists "Aula comments read" on public.aula_scada_comments;create policy "Aula comments read" on public.aula_scada_comments for select to authenticated using(true);
drop policy if exists "Aula comments insert" on public.aula_scada_comments;create policy "Aula comments insert" on public.aula_scada_comments for insert to authenticated with check(created_by=auth.uid() and exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin')));
drop policy if exists "Aula comments update" on public.aula_scada_comments;create policy "Aula comments update" on public.aula_scada_comments for update to authenticated using(exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin'))) with check(exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin')));
drop policy if exists "Aula comments delete" on public.aula_scada_comments;create policy "Aula comments delete" on public.aula_scada_comments for delete to authenticated using(exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin')));
grant select on public.aula_scada_members,public.aula_scada_screens,public.aula_scada_comments to authenticated;grant insert,update,delete on public.aula_scada_screens,public.aula_scada_comments to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('aula-scada','aula-scada',false,12582912,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=12582912,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "Aula images read" on storage.objects;create policy "Aula images read" on storage.objects for select to authenticated using(bucket_id='aula-scada');
drop policy if exists "Aula images insert" on storage.objects;create policy "Aula images insert" on storage.objects for insert to authenticated with check(bucket_id='aula-scada' and exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin')));
drop policy if exists "Aula images update" on storage.objects;create policy "Aula images update" on storage.objects for update to authenticated using(bucket_id='aula-scada' and exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin'))) with check(bucket_id='aula-scada' and exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin')));
drop policy if exists "Aula images delete" on storage.objects;create policy "Aula images delete" on storage.objects for delete to authenticated using(bucket_id='aula-scada' and exists(select 1 from public.aula_scada_members m where m.user_id=auth.uid() and m.role in('editor','admin')));
